import ULThemeCard from "@/components/ULThemeCard";
import ULThemePageLayout from "@/components/ULThemePageLayout";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import AlternativeLogins from "./components/AlternativeLogins";
import Footer from "./components/Footer";
import Header from "./components/Header";
import LoginIdForm from "./components/LoginIdForm";
import { useLoginIdManager } from "./hooks/useLoginIdManager";
import { applyScreenThemeOverrides } from "@/utils/theme/themeOverrides";

function LoginIdScreen() {
  // Extracting attributes from hook made out of LoginIdInstance class of Auth0 React ACUL SDK
  const { loginId, texts, locales, isPasskeyEnabled, alternateConnections } =
    useLoginIdManager();

  // Check whether separator component needs to be rendered based on passkey or other social connections
  const showSeparator =
    isPasskeyEnabled ||
    (alternateConnections && alternateConnections.length > 0);

  // Other Texts
  const separatorText = texts?.separatorText || locales?.page?.orText;
  document.title = texts?.pageTitle || locales?.page?.title;

  // Variables CSS que esta pantalla protege del Dashboard branding.
  // Edita estos valores para personalizar el aspecto de la pantalla de login-id
  // sin afectar las demás pantallas.
  const LOGIN_ID_THEME_OVERRIDES = [
    {
      variable: "--ul-theme-page-bg-background-color",
      value: "#803571", // Color de fondo de la pantalla
    },
    {
      variable: "--ul-theme-color-primary-button",
      value: "#2563eb", // Azul de acción para el botón principal
    },
    {
      // 🖼️ Logo específico para esta pantalla.
      // IMPORTANTE: El valor debe ir entre comillas dobles anidadas porque la variable
      // CSS se almacena como string entre comillas (igual que lo hace themeFlatteners).
      // extractTokenValue() las elimina automáticamente al leerla.
      // ✅ Mismo logo que el Dashboard → mantiene consistencia entre pantallas.
      // 💡 Para un logo DIFERENTE por pantalla, simplemente cambia la URL aquí.
      variable: "--ul-theme-widget-logo-url",
      value: '"https://static-cdn.jtvnw.net/jtv_user_pictures/7f4f6049-7ee2-41ee-bd3a-86f9b11e2c17-profile_image-70x70.png"',
    },
    {
      variable: "--ul-theme-widget-logo-position",
      value: "center",
    },
    {
      // 🔑 CLAVE: Fuerza el layout a "bottom" para que los botones sociales
      // siempre aparezcan ABAJO del formulario, ignorando la config del Dashboard.
      variable: "--ul-theme-widget-social-buttons-layout",
      value: "bottom",
    },
  ];

  // Aplica el tema del Dashboard de Auth0 primero (branding general del tenant)
  applyAuth0Theme(loginId);
  
  // Luego aplica los overrides específicos de esta pantalla (tienen mayor prioridad)
  applyScreenThemeOverrides(LOGIN_ID_THEME_OVERRIDES);

  return (
    // Applying UDS theme overrides using the "theme-universal" class
    <ULThemePageLayout className="theme-universal">
      {/*
        Layout de la card ampliado a max-w-[640px] para acomodar el diseño horizontal.
        En pantallas pequeñas (< md) el layout regresa a columna vertical.
      */}
      <ULThemeCard className="w-full max-w-[800px] gap-0">
        {/* Ejercicio 1: Banner de aviso de acceso seguro — ancho completo */}
        <div className="bg-blue-50 border border-blue-600 text-blue-600 text-sm px-4 py-2 rounded mb-4 text-center">
          🔒 Acceso seguro — Solo para usuarios autorizados
        </div>

        {/* Header (logo + título) — ancho completo */}
        <Header />

        {/*
          Layout de dos columnas:
          - Columna izquierda: formulario + mensaje de ayuda + footer
          - Separador vertical con texto "O"
          - Columna derecha: botones de conexiones sociales / passkey
          En móvil (< md) cambia a columna vertical con separador horizontal.
        */}
        <div className="flex flex-col md:flex-row gap-6 items-stretch mt-2">

          {/* ── Columna izquierda: formulario ── */}
          <div className="flex-1 flex flex-col">
            <LoginIdForm />
            {/* Ejercicio 3: Mensaje de ayuda antes del Footer */}
            <div className="text-center mt-2 mb-2 text-xs text-gray-500">
              ¿Problemas para acceder?{" "}
              <a href="mailto:soporte@coppel.com" className="text-blue-600 underline">
                Contacta a soporte
              </a>
            </div>
            <Footer />
          </div>

          {/* ── Separador: vertical en desktop, horizontal en móvil ── */}
          {showSeparator && (
            <>
              {/* Separador horizontal visible solo en móvil */}
              <div className="flex md:hidden items-center gap-3 my-1">
                <div className="flex-1 h-px bg-gray-200" />
                <span className="text-xs text-gray-400 shrink-0">{separatorText}</span>
                <div className="flex-1 h-px bg-gray-200" />
              </div>

              {/* Separador vertical visible solo en desktop */}
              <div className="hidden md:flex flex-col items-center gap-2 py-1">
                <div className="flex-1 w-px bg-gray-200" />
                <span className="text-xs text-gray-400 rotate-0 whitespace-nowrap">{separatorText}</span>
                <div className="flex-1 w-px bg-gray-200" />
              </div>
            </>
          )}

          {/* ── Columna derecha: botones sociales ── */}
          {(alternateConnections && alternateConnections.length > 0 || isPasskeyEnabled) && (
            <div className="flex flex-col justify-center gap-3 md:min-w-[300px]">
              <AlternativeLogins />
            </div>
          )}
        </div>
      </ULThemeCard>
    </ULThemePageLayout>
  );
}

export default LoginIdScreen;
